"""Write the OpenAPI contract and regenerate the TypeScript client."""

from __future__ import annotations

import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

from lunarhunt_api.main import app

HEADER = (
    "// Generated by @hey-api/openapi-ts from packages/contracts/openapi.json. "
    'Do not edit; regenerate (see AGENTS.md, "uv run export-openapi").\n'
)
CONTRACT_RELATIVE = Path("packages/contracts/openapi.json")
CLIENT_RELATIVE = Path("packages/api-client/src")
_SOURCE_SUFFIXES = {".ts", ".tsx", ".mts", ".cts"}


def repo_root() -> Path:
    here = Path(__file__).resolve()
    for parent in here.parents:
        if (parent / "pnpm-workspace.yaml").is_file():
            return parent
    message = "Could not find the repository root (pnpm-workspace.yaml)."
    raise RuntimeError(message)


def render_openapi() -> str:
    spec = app.openapi()
    return json.dumps(spec, indent=2, sort_keys=True) + "\n"


def _run_openapi_ts(root: Path, openapi_path: Path, output_dir: Path) -> None:
    output_dir.mkdir(parents=True, exist_ok=True)
    command = [
        "pnpm",
        "exec",
        "openapi-ts",
        "--input",
        str(openapi_path),
        "--output",
        str(output_dir),
        "--client",
        "@hey-api/client-fetch",
    ]
    try:
        subprocess.run(command, cwd=root, check=True)
    except subprocess.CalledProcessError as exc:
        raise SystemExit(exc.returncode) from exc


def _stamp(directory: Path) -> None:
    for path in sorted(directory.rglob("*")):
        if not path.is_file() or path.suffix not in _SOURCE_SUFFIXES:
            continue
        text = path.read_text(encoding="utf-8")
        if text.startswith(HEADER):
            continue
        path.write_text(HEADER + text, encoding="utf-8")


def _files(directory: Path) -> dict[Path, bytes]:
    return {
        path.relative_to(directory): path.read_bytes()
        for path in directory.rglob("*")
        if path.is_file()
    }


def _diff_trees(generated: Path, committed: Path) -> list[str]:
    if not committed.exists():
        return [f"missing {CLIENT_RELATIVE.as_posix()}"]
    generated_files = _files(generated)
    committed_files = _files(committed)
    problems: list[str] = []
    prefix = CLIENT_RELATIVE.as_posix()
    for name in sorted(set(generated_files) - set(committed_files)):
        problems.append(f"missing generated file {prefix}/{name.as_posix()}")
    for name in sorted(set(committed_files) - set(generated_files)):
        problems.append(f"unexpected file {prefix}/{name.as_posix()}")
    for name in sorted(set(generated_files) & set(committed_files)):
        if generated_files[name] != committed_files[name]:
            problems.append(f"differs {prefix}/{name.as_posix()}")
    return problems


def main() -> None:
    check = "--check" in sys.argv[1:]
    unknown = [arg for arg in sys.argv[1:] if arg != "--check"]
    if unknown:
        sys.stderr.write(f"Unknown arguments: {' '.join(unknown)}\n")
        raise SystemExit(2)

    root = repo_root()
    spec = render_openapi()
    with tempfile.TemporaryDirectory(prefix="lunarhunt-openapi-") as tmp:
        temp_root = Path(tmp)
        openapi_path = temp_root / "openapi.json"
        client_path = temp_root / "client"
        openapi_path.write_text(spec, encoding="utf-8")
        _run_openapi_ts(root, openapi_path, client_path)
        _stamp(client_path)

        contract_path = root / CONTRACT_RELATIVE
        client_dest = root / CLIENT_RELATIVE
        if check:
            problems: list[str] = []
            if not contract_path.is_file() or contract_path.read_text(encoding="utf-8") != spec:
                problems.append(f"differs {CONTRACT_RELATIVE.as_posix()}")
            problems.extend(_diff_trees(client_path, client_dest))
            if problems:
                sys.stderr.write(
                    "Contract drift. Run `uv run export-openapi` and commit the result.\n",
                )
                for problem in problems:
                    sys.stderr.write(f"- {problem}\n")
                raise SystemExit(1)
            return

        contract_path.parent.mkdir(parents=True, exist_ok=True)
        contract_path.write_text(spec, encoding="utf-8")
        if client_dest.exists():
            shutil.rmtree(client_dest)
        shutil.copytree(client_path, client_dest)
